 import unittest
from candidate import is_simple_power

class TestIsSimplePower(unittest.TestCase):
    def test_simple_power_normalcase(self):
        self.assertTrue(is_simple_power(1, 4))

    def test_simple_power_positive(self):
        self.assertTrue(is_simple_power(2, 2))

    def test_simple_power_large(self):
        self.assertTrue(is_simple_power(8, 2))

    def test_simple_power_negative(self):
        self.assertTrue(is_simple_power(-8, 2))

    def test_simple_power_non_power(self):
        self.assertFalse(is_simple_power(3, 2))

    def test_simple_power_one(self):
        self.assertTrue(is_simple_power(1, 1))

    def test_simple_power_zero(self):
        self.assertFalse(is_simple_power(0, any))

    def test_simple_power_non_number(self):
        self.assertRaises(TypeError, is_simple_power, "3", 2)

    def test_simple_power_negative_n(self):
        self.assertFalse(is_simple_power(8, -2))

    def test_simple_power_fractional_n(self):
        self.assertFalse(is_simple_power(2, 0.5))

if __name__ == '__main__':
    unittest.main()
